import{_ as e,o as t,c as i,a2 as r}from"./chunks/framework.BS2VDJqE.js";const p=JSON.parse('{"title":"Download","description":"","frontmatter":{},"headers":[],"relativePath":"download.md","filePath":"download.md","lastUpdated":1795797533000}'),s={name:"download.md"};function l(n,a,o,h,d,c){return t(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="download" tabindex="-1">Download <a class="header-anchor" href="#download" aria-label="Permalink to &quot;Download&quot;">​</a></h1><p>Ciyue runs on Android, Windows, Linux, and macOS.</p><h2 id="stable" tabindex="-1">Stable <a class="header-anchor" href="#stable" aria-label="Permalink to &quot;Stable&quot;">​</a></h2><p>Download the <a href="https://github.com/mumu-lhl/Ciyue/releases/latest" target="_blank" rel="noreferrer">latest release</a> — recommended for most users.</p><h3 id="android" tabindex="-1">Android <a class="header-anchor" href="#android" aria-label="Permalink to &quot;Android&quot;">​</a></h3><p><a href="https://github.com/mumu-lhl/Ciyue/releases/latest"><img src="https://github.com/NeoApplications/Neo-Backup/raw/034b226cea5c1b30eb4f6a6f313e4dadcbb0ece4/badge_github.png" alt="Get it on GitHub" height="80"></a><a href="https://f-droid.org/packages/org.eu.mumulhl.ciyue/"><img src="https://f-droid.org/badge/get-it-on.png" alt="Get it on F-Droid" height="80"></a><a href="https://apps.obtainium.imranr.dev/redirect?r=obtainium://add/https://github.com/mumu-lhl/Ciyue"><img src="https://raw.githubusercontent.com/ImranR98/Obtainium/main/assets/graphics/badge_obtainium.png" alt="Get it on Obtainium" height="80"></a></p><p>Tip: <a href="https://obtainium.imranr.dev/" target="_blank" rel="noreferrer">Obtainium</a> tracks GitHub releases directly, so you get updates faster than F-Droid, whose builds can lag behind.</p><h3 id="windows" tabindex="-1">Windows <a class="header-anchor" href="#windows" aria-label="Permalink to &quot;Windows&quot;">​</a></h3><p>Download the installer (<code>ciyue-installer.exe</code>) or portable ZIP from the <a href="https://github.com/mumu-lhl/Ciyue/releases/latest" target="_blank" rel="noreferrer">latest release</a>.</p><h3 id="linux" tabindex="-1">Linux <a class="header-anchor" href="#linux" aria-label="Permalink to &quot;Linux&quot;">​</a></h3><ul><li><p><strong>Flatpak</strong>: download <code>ciyue-x86_64.flatpak</code> from a release and install it with:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">flatpak</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --user</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./ciyue-x86_64.flatpak</span></span></code></pre></div></li><li><p><strong>Arch Linux</strong>: install from the <a href="https://aur.archlinux.org/packages/ciyue" target="_blank" rel="noreferrer">AUR</a> or <a href="https://github.com/archlinuxcn/repo/tree/master/archlinuxcn/ciyue" target="_blank" rel="noreferrer">archlinuxcn</a> repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">yay</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -S</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ciyue</span></span></code></pre></div></li><li><p><strong>AppImage</strong>:</p><ul><li>via <a href="https://github.com/ivan-hc/AppMan" target="_blank" rel="noreferrer">AppMan</a> (rootless): <code>appman -i ciyue</code></li><li>via <a href="https://github.com/ivan-hc/AM" target="_blank" rel="noreferrer">AM</a>: <code>am -i ciyue</code></li></ul></li></ul><h3 id="macos" tabindex="-1">macOS <a class="header-anchor" href="#macos" aria-label="Permalink to &quot;macOS&quot;">​</a></h3><p>Download the DMG (<code>ciyue-macos.dmg</code>) from the <a href="https://github.com/mumu-lhl/Ciyue/releases/latest" target="_blank" rel="noreferrer">latest release</a>.</p><p>Ciyue needs macOS 12 (Monterey) or later. The DMG is a universal build, so it runs on both Apple Silicon and Intel Macs. Launch at login needs macOS 13 (Ventura) or later; on macOS 12 the setting has no effect.</p><h2 id="nightly" tabindex="-1">Nightly <a class="header-anchor" href="#nightly" aria-label="Permalink to &quot;Nightly&quot;">​</a></h2><p>Nightly builds are published every night from the latest main branch. They include the newest features, but may be unstable. Download the <a href="https://github.com/mumu-lhl/Ciyue/releases/tag/nightly" target="_blank" rel="noreferrer">latest nightly build</a>.</p><h2 id="after-installing" tabindex="-1">After installing <a class="header-anchor" href="#after-installing" aria-label="Permalink to &quot;After installing&quot;">​</a></h2><p>Ciyue does not ship with dictionaries. See <a href="./guide/getting-started.html#download-dictionaries">Download dictionaries</a> to add your first dictionary.</p>',18)])])}const g=e(s,[["render",l]]);export{p as __pageData,g as default};
